<script setup lang="ts">
import { computed, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api } from '../api';

const route = useRoute(); const router = useRouter(); const matchId = computed(() => String(route.query.matchId ?? ''));
const feedback = ref('helpful'); const note = ref(''); const busy = ref(false); const error = ref(''); const complete = ref(false);
async function save(shareLater: boolean) { if (!matchId.value) return; busy.value = true; error.value = ''; try { await api.post(`/api/v1/peer-conversations/${encodeURIComponent(matchId.value)}/feedback`, { feedback: feedback.value, note: note.value, shareLater }); complete.value = true; } catch (cause: any) { error.value = cause?.message ?? '这份感受暂时没有保存成功'; } finally { busy.value = false; } }
</script>

<template>
  <section class="goodnight-page peer-graduation-page">
    <header class="graduation-hero"><span>匿名同路</span><h1>这段同行<br>已经走到这里</h1><p>谢谢你们都认真守住了边界。</p></header>
    <article class="graduate-card"><div class="lantern">✦</div><p class="kicker">会话已结束</p><h2>把这一点感受留给自己</h2><p>不需要评价谁，也不需要给出更多解释。你的回答只会用来改善这段同行的安全体验。</p><div class="feelings"><button v-for="option in [{ value: 'helpful', label: '有被接住' }, { value: 'unchanged', label: '没什么变化' }, { value: 'uncomfortable', label: '有点不舒服' }]" :key="option.value" :class="{ selected: feedback === option.value }" @click="feedback = option.value">{{ option.label }}</button></div><label>想留下的一句话（可选）<textarea v-model="note" maxlength="500" placeholder="这里不会成为公开内容，除非你稍后明确同意分享。" /></label><p v-if="complete" class="success-note">已经收好这份感受。谢谢你认真地走完这一段。</p><button class="share" :disabled="busy || complete" @click="save(true)">{{ busy ? '正在保存…' : '以后也想把后来留给同路人' }}</button><button class="later" :disabled="busy || complete" @click="save(false)">{{ complete ? '已完成' : '先把它留给自己' }}</button><button class="back" @click="router.push('/pages/peers/index')">回到同路</button></article><p v-if="error" class="error-note">{{ error }}</p>
  </section>
</template>

