(--gn-danger);text-align:center}
.graduation-hero{position:relative;overflow:hidden}.graduation-hero::after{position:absolute;right:-10px;bottom:-10px;width:228px;height:194px;background:url('../assets/goodnight/peer/peer-night-tree.png') right bottom/contain no-repeat;content:'';opacity:.78;pointer-events:none;-webkit-mask-image:radial-gradient(ellipse at 100% 0%,#000 42%,transparent 88%);mask-image:radial-gradient(ellipse at 100% 0%,#000 42%,transparent 88%)}.graduation-hero>*{position:relative;z-index:1}
